/**
 * ChatPanel — slide-out chat for MessageCenter (topbar inbox).
 *
 * Reuses `useMessages` hook (already joins/leaves SignalR room internally).
 */
import React, { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { navigateToUrl } from 'single-spa';
import type { ConversationSummary } from '../../../services/message/conversationTypes';
import { ChatTab } from '../../shared';
import { useMessages } from '../../../hooks/useMessages';
import { useAppSelector } from '../../../store/hooks';
import { useAppToast } from '../../../hooks/useAppToast';
import { appPath } from '../../../config/appRoutes';
import { scykRoutes } from '../../../config/scykRoutes';
import { isStandalone } from '../../../dev/isStandalone';
import styles from './ChatPanel.module.css';

function getEntityIcon(entityType: 'ticket' | 'task' | 'incident'): string {
  switch (entityType) {
    case 'ticket':
      return 'fas fa-ticket-alt';
    case 'task':
      return 'fas fa-tasks';
    case 'incident':
      return 'fas fa-exclamation-triangle';
    default:
      return 'fas fa-comment-dots';
  }
}

function openDetailRoute(
  conv: ConversationSummary,
  navigate: ReturnType<typeof useNavigate>,
  onCrossAppUnavailable: () => void,
): void {
  switch (conv.entityType) {
    case 'incident':
      navigate(appPath(scykRoutes.incidentDetail(conv.entityId)));
      return;
    case 'ticket':
      if (isStandalone) {
        onCrossAppUnavailable();
        return;
      }
      navigateToUrl(`/task/tickets/${conv.entityId}`);
      return;
    case 'task':
      if (isStandalone) {
        onCrossAppUnavailable();
        return;
      }
      navigateToUrl(`/task/tasks/${conv.entityId}`);
      return;
    default:
      if (isStandalone) {
        onCrossAppUnavailable();
        return;
      }
      navigateToUrl(`/task/tickets/${conv.entityId}`);
  }
}

interface ChatPanelProps {
  conversation: ConversationSummary;
}

export const ChatPanel: React.FC<ChatPanelProps> = ({ conversation }) => {
  const currentUser = useAppSelector((s) => s.auth.user);
  const navigate = useNavigate();
  const toast = useAppToast();

  const onCrossAppUnavailable = useCallback(() => {
    toast.info('Ticket/task mở trên shell prod (@linm/task), không có trong standalone SCYK.');
  }, [toast]);

  const goToDetail = useCallback(() => {
    openDetailRoute(conversation, navigate, onCrossAppUnavailable);
  }, [navigate, conversation, onCrossAppUnavailable]);

  const {
    chatMessages,
    sendMessage,
    hasMoreChat,
    loading,
    loadMoreChat,
  } = useMessages(
    conversation.entityType as 'ticket' | 'task' | 'incident',
    conversation.entityId,
  );

  return (
    <div className={styles.panel}>
      <div className={styles.header}>
        <div className={styles.headerIcon}>
          <i className={getEntityIcon(conversation.entityType)} />
        </div>
        <div className={styles.headerInfo}>
          <span className={styles.headerCode}>{conversation.entityIdCode}</span>
          <span className={styles.headerTitle}>{conversation.entityTitle}</span>
        </div>
        <span className={styles.headerStatus}>{conversation.entityStatus}</span>
        <button
          className={styles.detailBtn}
          onClick={goToDetail}
          title="Xem chi tiết"
          type="button"
        >
          <i className="fas fa-external-link-alt" />
          <span>Chi tiết</span>
        </button>
      </div>

      <div className={styles.chatWrap}>
        <ChatTab
          entityId={conversation.entityId}
          entityType={conversation.entityType as 'ticket' | 'task'}
          messages={chatMessages}
          onSendMessage={sendMessage}
          currentUserId={currentUser?.id ?? ''}
          hasMore={hasMoreChat}
          loading={loading}
          onLoadMore={loadMoreChat}
        />
      </div>
    </div>
  );
};
