import React from 'react';
import { AppLayout as NavContentShell } from '@linm-soft/common-components';
import { isStandalone } from '../../../dev/isStandalone';
import { StandaloneAppLayout } from './StandaloneAppLayout';
import { RouteNavTitleSync } from './RouteNavTitleSync';

/**
 * Shell layout router:
 * - Production / `yarn start`: @linm/nav owns Sidebar + Topbar; content shell only.
 * - `yarn start:std`: full local Sidebar + Topbar (static menu fallback).
 */
export const DomainShell: React.FC = () => {
  if (isStandalone) {
    return <StandaloneAppLayout />;
  }

  return (
    <>
      <RouteNavTitleSync />
      <NavContentShell />
    </>
  );
};

export default DomainShell;
