import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { navigateToUrl } from 'single-spa';
import {
  getHomePath,
  isPathAllowed,
  usePermissionsReady,
  hasValidAuthToken,
} from '@linm-soft/common-components';
import { useAppSelector } from '../../store/hooks';
import { UserRole } from '../../models/User';
import { isStandalone } from '../../dev/isStandalone';
import { APP_UI_PREFIX, appPath, normalizeMenuPathToRoute, SCYK_DEFAULT_ROUTE } from '../../config/appRoutes';
import {
  getHomePathStandalone,
  isPathAllowedStandalone,
} from '../../utils/navUtils.standalone';

interface ProtectedRouteProps {
  children: React.ReactNode;
  allowedRoles?: UserRole[];
}

const PermissionsBootstrapLoading: React.FC = () => (
  <div
    style={{
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '40vh',
      color: 'var(--ds-color-text-muted, #666)',
      gap: 12,
    }}
    aria-live="polite"
    aria-busy="true"
  >
    <i className="fas fa-spinner fa-spin" aria-hidden="true" />
    <span>Đang tải menu…</span>
  </div>
);

/**
 * Auth + menu guard.
 * Shell: allowedPaths from @linm/nav permission cache.
 * Standalone: static navUtils.standalone fallback.
 */
export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({
  children,
  allowedRoles,
}) => {
  const { isAuthenticated, user } = useAppSelector((state) => state.auth);
  const location = useLocation();
  const permissionsReady = usePermissionsReady();

  if (!isAuthenticated || !hasValidAuthToken()) {
    navigateToUrl('/login');
    return null;
  }

  if (location.pathname === '/' || location.pathname === appPath()) {
    if (!isStandalone && !permissionsReady) {
      return <PermissionsBootstrapLoading />;
    }

    const homePath = isStandalone
      ? getHomePathStandalone(user?.role, user?.package, user?.defaultMenuUrl)
      : getHomePath(user?.role, user?.package, user?.defaultMenuUrl);

    const target = homePath?.startsWith(`/${APP_UI_PREFIX}`)
      ? homePath
      : appPath(normalizeMenuPathToRoute(homePath));
    return <Navigate to={target} replace />;
  }

  if (allowedRoles && allowedRoles.length > 0 && user) {
    if (!allowedRoles.includes(user.role)) {
      if (isStandalone) return <Navigate to="/unauthorized" replace />;
      navigateToUrl('/unauthorized');
      return null;
    }
  }

  const pathOk = isStandalone
    ? isPathAllowedStandalone(user?.role, user?.package, location.pathname)
    : isPathAllowed(user?.role, user?.package, location.pathname);

  if (user && !pathOk) {
    if (isStandalone) return <Navigate to="/unauthorized" replace />;
    navigateToUrl('/unauthorized');
    return null;
  }

  return <>{children}</>;
};

export default ProtectedRoute;
