/**
 * useEntitySubscription — per-entity notification mute/subscribe hook.
 *
 * Fetches the current user's mute preference for a specific ticket or task,
 * and exposes a toggleMute() function to update it via the BFF API.
 *
 * Usage:
 *   const { isMuted, toggleMute, loading } = useEntitySubscription('ticket', ticketId);
 *   const { isMuted, toggleMute, loading } = useEntitySubscription('task', taskId);
 *
 * When entityId is undefined (loading state), the hook returns a neutral default.
 */

import { useCallback, useEffect, useState } from 'react';
import { subscriptionService } from '../services/notifications';

interface UseEntitySubscriptionReturn {
  /** True when the user has muted NEW_MESSAGE notifications for this entity. */
  isMuted: boolean;
  /** Toggle mute state. Optimistically updates UI; rolls back on error. */
  toggleMute: () => Promise<void>;
  /** True while the initial preference is being fetched or while toggling. */
  loading: boolean;
  /** Last error message, if any. */
  error: string | null;
}

export const useEntitySubscription = (
  entityType: 'ticket' | 'task' | 'incident',
  entityId: string | undefined,
): UseEntitySubscriptionReturn => {
  const [isMuted,  setIsMuted]  = useState(false);
  const [loading,  setLoading]  = useState(false);
  const [error,    setError]    = useState<string | null>(null);

  // ── Fetch initial state ───────────────────────────────────────────────────

  useEffect(() => {
    if (!entityId) return;
    let cancelled = false;
    setLoading(true);
    setError(null);

    subscriptionService.getSubscription(entityType, entityId)
      .then((data) => {
        if (!cancelled) setIsMuted(data.isMuted);
      })
      .catch((err) => {
        if (!cancelled) {
          console.warn('[useEntitySubscription] Failed to fetch subscription:', err);
          setError('Không thể tải trạng thái thông báo');
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [entityType, entityId]);

  // ── Toggle mute (optimistic update) ──────────────────────────────────────

  const toggleMute = useCallback(async () => {
    if (!entityId || loading) return;
    const previousState = isMuted;
    const nextState = !isMuted;

    // Optimistic update
    setIsMuted(nextState);
    setLoading(true);
    setError(null);

    try {
      const result = await subscriptionService.updateSubscription(entityType, entityId, nextState);
      setIsMuted(result.isMuted);
      console.log(
        `[useEntitySubscription] ${entityType} ${entityId} → isMuted=${result.isMuted}`,
      );
    } catch (err) {
      // Roll back optimistic update
      setIsMuted(previousState);
      setError('Không thể cập nhật trạng thái thông báo');
      console.error('[useEntitySubscription] toggleMute failed:', err);
    } finally {
      setLoading(false);
    }
  }, [entityType, entityId, isMuted, loading]);

  return { isMuted, toggleMute, loading, error };
};
