/**
 * SignalR collaboration hub — type definitions.
 *
 * The backend CollaborationHub sends these events to the client.
 * The client joins/leaves named groups via hub methods.
 *
 * Unified messaging: NewMessage / MessageEdited / MessageDeleted replace
 * the old NewComment / CommentEdited / CommentDeleted / NewChatMessage events.
 *
 * Personal events (ReceiveNotification) are delivered via User_{userId} group,
 * which the server auto-joins on every connection.
 */

import { BffMessageDto } from '../message/responseModel';
import type { NotificationDto } from '../notifications/types';

// ── Group names (resolved at runtime) ───────────────────────────────────────

export const ticketGroup = (ticketId: string) => `Ticket_${ticketId}`;
export const taskGroup   = (taskId: string)   => `Task_${taskId}`;
export const deptGroup   = (deptId: string)   => `Dept_${deptId}`;

// ── Hub method names the CLIENT can invoke ───────────────────────────────────

export const HubMethod = {
  JoinTicketRoom:    'JoinTicketRoom',
  LeaveTicketRoom:   'LeaveTicketRoom',
  JoinTaskRoom:      'JoinTaskRoom',
  LeaveTaskRoom:     'LeaveTaskRoom',
  JoinIncidentRoom:  'JoinIncidentRoom',
  LeaveIncidentRoom: 'LeaveIncidentRoom',
} as const;

// ── Server-to-client event names ─────────────────────────────────────────────

export const HubEvent = {
  // Unified messaging events
  NewMessage:           'NewMessage',
  MessageEdited:        'MessageEdited',
  MessageDeleted:       'MessageDeleted',
  // Status events
  TicketStatusChanged:  'TicketStatusChanged',
  TaskStatusChanged:    'TaskStatusChanged',
  // Personal notification event (delivered to User_{userId} group)
  ReceiveNotification:  'ReceiveNotification',
  // Department broadcast notification (delivered to Dept_{deptId} group)
  DeptNotification:     'DeptNotification',
} as const;

export type HubEventName = (typeof HubEvent)[keyof typeof HubEvent];

// ── Payloads ─────────────────────────────────────────────────────────────────

export interface NewMessageEvent {
  entityId:   string;
  entityType: 'ticket' | 'task' | 'incident';
  message:    BffMessageDto;
}

export interface MessageEditedEvent {
  entityId:   string;
  entityType: 'ticket' | 'task' | 'incident';
  message:    BffMessageDto;
}

export interface MessageDeletedEvent {
  entityId:   string;
  entityType: 'ticket' | 'task' | 'incident';
  messageId:  string;
}

export interface TicketStatusChangedEvent {
  ticketId:  string;
  status:    string;
  actorName: string;
}

export interface TaskStatusChangedEvent {
  taskId:    string;
  status:    string;
  actorName: string;
}

export type HubEventPayloadMap = {
  [HubEvent.NewMessage]:          NewMessageEvent;
  [HubEvent.MessageEdited]:       MessageEditedEvent;
  [HubEvent.MessageDeleted]:      MessageDeletedEvent;
  [HubEvent.TicketStatusChanged]: TicketStatusChangedEvent;
  [HubEvent.TaskStatusChanged]:   TaskStatusChangedEvent;
  [HubEvent.ReceiveNotification]: NotificationDto;
  [HubEvent.DeptNotification]:    NotificationDto;
};
