import type { User } from '../models/User';
import { UserRole } from '../models/User';

function normCompanyCode(value: string): string {
  return value.trim().toUpperCase();
}

function buildAllowedCompanySet(
  allowedCompanyIds: string[] | undefined,
  homeCompanyId: string | undefined,
): Set<string> {
  const set = new Set((allowedCompanyIds ?? []).map(normCompanyCode));
  if (homeCompanyId) set.add(normCompanyCode(homeCompanyId));
  return set;
}

export function isTenantSwitchAllowedForUser(
  selectedId: string,
  user: Pick<User, 'canViewAllCompanies' | 'allowedCompanyIds' | 'companyId' | 'role'> | null | undefined,
): boolean {
  if (!user) return false;
  if (user.canViewAllCompanies === true || user.role === UserRole.Admin) return true;

  const allowed = buildAllowedCompanySet(user.allowedCompanyIds, user.companyId);
  if (allowed.size === 0) return true;

  return allowed.has(normCompanyCode(selectedId));
}
