import { useMemo } from 'react';
import { isStandalone } from '../dev/isStandalone';
import { hasPermissionCode, usePermissionCodes } from './usePermissionCodes';

/** Auth CSV — medical-incidents navigation set. */
export const FALL_WARNING_PERM = {
  read: 'medical-incidents:fall-location-warnings:read',
  list: 'medical-incident:fall-warning:list',
  write: 'medical-incidents:fall-location-warnings:write',
} as const;

/**
 * List toolbar flags — permission cache fallback (`voucher-permissions.md` list-only pattern).
 */
export function useFallWarningListActions() {
  const codes = usePermissionCodes();

  return useMemo(() => {
    if (isStandalone) {
      return {
        canRead: true,
        canCreate: true,
        canUpdate: true,
        canDelete: true,
      };
    }

    const canRead =
      hasPermissionCode(codes, FALL_WARNING_PERM.read)
      || hasPermissionCode(codes, FALL_WARNING_PERM.list);
    const canWrite = hasPermissionCode(codes, FALL_WARNING_PERM.write);

    return {
      canRead,
      canCreate: canWrite,
      canUpdate: canWrite,
      canDelete: canWrite,
    };
  }, [codes]);
}
