import { stripAppPrefix } from './appRoutes';
import { scykRoutes } from './scykRoutes';

/** Page title theo URL SCYK (segment tiếng Việt). */
export function resolvePageTitle(pathname: string): string {
  const path = stripAppPrefix(pathname);

  if (path === `/${scykRoutes.home}`) return 'Danh Sách Sự Cố Y Khoa';
  if (path === `/${scykRoutes.reportStats}`) return 'Báo Cáo Thống Kê SCYK';
  if (path === `/${scykRoutes.reportServiceMismatch}`) return 'Báo Cáo Nhầm Dịch Vụ';
  if (path === `/${scykRoutes.reportFall}`) return 'Báo Cáo Sự Cố Té Ngã';
  if (path === `/${scykRoutes.incidentNew}`) return 'Báo Cáo Sự Cố Mới';
  if (path.startsWith(`/${scykRoutes.reportDaily}`)) return 'Báo Cáo Hằng Ngày';
  if (path.startsWith(`/${scykRoutes.home}/`)) return 'Chi Tiết Sự Cố';
  if (path === `/${scykRoutes.fallWarnings}`) return 'Cảnh Báo Vị Trí Té Ngã';
  if (path === `/${scykRoutes.fallWarningNew}`) return 'Thêm Cảnh Báo Vị Trí Té Ngã';
  if (path.startsWith(`/${scykRoutes.fallWarnings}/`)) return 'Chi Tiết Cảnh Báo Vị Trí Té Ngã';

  return 'QL Sự Cố Y Khoa';
}
