import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';
import {
  clearActiveCompanyId,
  clearAuthTokens,
  clearAuthUser,
  clearPermissionsCache,
  getActiveCompanyId,
  getAuthToken,
  getAuthUser,
  setActiveCompanyId,
  setAuthTokens,
  setAuthUser,
} from '@linm-soft/common-components';
import { User } from '../../models/User';
import { authService } from '../../services/auth';
import { signalRService } from '../../services/signalr';
import { appSettings } from '../../config/appSettings';
import { isTenantSwitchAllowedForUser } from '../../utils/companyTenantMatch';

function notifyAuthChanged(): void {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('linm:auth:changed'));
  }
}

interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  loading: boolean;
  logoutLoading: boolean;
  error: string | null;
  requirePasswordChange: boolean;
}

const initialState: AuthState = {
  user: null,
  isAuthenticated: false,
  loading: false,
  logoutLoading: false,
  error: null,
  requirePasswordChange: false,
};

const loadPersistedAuth = (): Partial<AuthState> => {
  try {
    const token = getAuthToken();
    const user = getAuthUser() as User | null;

    if (token && user) {
      if (!getActiveCompanyId() && user.companyId) {
        setActiveCompanyId(user.companyId);
      }
      return {
        user,
        isAuthenticated: true,
        requirePasswordChange: user.requirePasswordChange ?? false,
      };
    }
  } catch (error) {
    console.error('Failed to load persisted auth:', error);
  }

  return {};
};

Object.assign(initialState, loadPersistedAuth());

export const login = createAsyncThunk(
  'auth/login',
  async ({
    username,
    password,
    activeCompanyId,
  }: {
    username: string;
    password: string;
    activeCompanyId?: string;
  }) => {
    const response = await authService.login(username, password, activeCompanyId);

    clearPermissionsCache();
    setAuthTokens({
      accessToken: response.token,
      refreshToken: response.refreshToken,
    });
    setAuthUser(response.user);
    if (response.user.companyId) setActiveCompanyId(response.user.companyId);
    notifyAuthChanged();

    if (appSettings.enableSignalR) {
      signalRService.start().catch((err) =>
        console.warn('[authSlice] SignalR start after login failed:', err),
      );
    }

    return response;
  },
);

export const logout = createAsyncThunk('auth/logout', async () => {
  try {
    await authService.logout();
  } catch (err) {
    console.error('[auth] Logout backend call failed (force clean-up applied):', err);
  }

  clearAuthTokens();
  clearAuthUser();
  clearActiveCompanyId();
  clearPermissionsCache();
  notifyAuthChanged();

  if (appSettings.enableSignalR) {
    signalRService.reset().catch(() => {
      /* ignore */
    });
  }
});

export const getCurrentUser = createAsyncThunk('auth/getCurrentUser', async () => {
  return authService.getCurrentUser();
});

export const switchCompany = createAsyncThunk('auth/switchCompany', async (companyId: string, { getState }) => {
  const user = (getState() as { auth: AuthState }).auth.user ?? (getAuthUser() as User | null);
  if (!user) throw new Error('Chưa đăng nhập');

  if (!isTenantSwitchAllowedForUser(companyId, user))
    throw new Error('Bạn không có quyền truy cập đơn vị cơ sở này.');

  setActiveCompanyId(companyId);
  notifyAuthChanged();
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('linm:company:changed', { detail: { companyId } }));
  }

  return { companyId };
});

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    clearError: (state) => {
      state.error = null;
    },
    setUser: (state, action: PayloadAction<User>) => {
      state.user = action.payload;
      state.isAuthenticated = true;
      setAuthUser(action.payload);
    },
    clearRequirePasswordChange: (state) => {
      state.requirePasswordChange = false;
      if (state.user) {
        state.user.requirePasswordChange = false;
        setAuthUser(state.user);
      }
    },
    updateUserFromRefresh: (state, action: PayloadAction<User>) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
        setAuthUser(state.user);
      }
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(login.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(login.fulfilled, (state, action) => {
        state.loading = false;
        state.user = action.payload.user;
        state.isAuthenticated = true;
        state.error = null;
        state.requirePasswordChange = action.payload.user.requirePasswordChange ?? false;
      })
      .addCase(login.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Đăng nhập thất bại';
        state.isAuthenticated = false;
        state.user = null;
        state.requirePasswordChange = false;
      })
      .addCase(logout.pending, (state) => {
        state.logoutLoading = true;
      })
      .addCase(logout.fulfilled, (state) => {
        state.logoutLoading = false;
        state.user = null;
        state.isAuthenticated = false;
        state.error = null;
        state.requirePasswordChange = false;
      })
      .addCase(logout.rejected, (state) => {
        state.logoutLoading = false;
        state.user = null;
        state.isAuthenticated = false;
        state.requirePasswordChange = false;
      })
      .addCase(getCurrentUser.fulfilled, (state, action) => {
        state.user = action.payload;
        state.isAuthenticated = true;
      })
      .addCase(switchCompany.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(switchCompany.fulfilled, (state) => {
        state.loading = false;
        state.error = null;
      })
      .addCase(switchCompany.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Chuyển đổi công ty thất bại';
      });
  },
});

export const { clearError, setUser, clearRequirePasswordChange, updateUserFromRefresh } =
  authSlice.actions;
export default authSlice.reducer;
