/**
 * Unified Message service facade.
 *
 * Single service for all entity types (ticket, task, approval, etc.)
 * and all message types (chat messages + threaded comments).
 */

import { UUID } from '../../models/common';
import { BffMessageDto, BffMessagesPaginatedResponse } from './responseModel';
import { CreateMessageRequest, UpdateMessageRequest } from './requestModel';
import { messageEndpoint } from './endpoint';

export const messageService = {
  getMessages: (
    entityType: string,
    entityId: UUID,
    type?: 'message' | 'comment',
    page: number = 1,
    pageSize: number = 20,
  ): Promise<BffMessagesPaginatedResponse> =>
    messageEndpoint.getMessages(entityType, entityId, type, page, pageSize),

  createMessage: (
    entityType: string,
    entityId: UUID,
    req: CreateMessageRequest,
  ): Promise<BffMessageDto> =>
    messageEndpoint.createMessage(entityType, entityId, req),

  updateMessage: (
    entityType: string,
    entityId: UUID,
    messageId: UUID,
    req: UpdateMessageRequest,
  ): Promise<BffMessageDto> =>
    messageEndpoint.updateMessage(entityType, entityId, messageId, req),

  deleteMessage: (
    entityType: string,
    entityId: UUID,
    messageId: UUID,
  ): Promise<void> =>
    messageEndpoint.deleteMessage(entityType, entityId, messageId),
};
