import { useEffect, useState } from 'react';
import {
  getPermissionsCacheEntry,
  PERMISSION_READY,
} from '@linm-soft/common-components';

function readPermissionCodes(): string[] {
  const payload = getPermissionsCacheEntry()?.payload;
  const codes = payload?.permissionCodes;
  return Array.isArray(codes)
    ? codes.filter((c): c is string => typeof c === 'string')
    : [];
}

/** Permission codes from @linm/nav cache — fallback until init-data formPermissions. */
export function usePermissionCodes(): string[] {
  const [codes, setCodes] = useState<string[]>(() => readPermissionCodes());

  useEffect(() => {
    const sync = () => setCodes(readPermissionCodes());
    sync();
    window.addEventListener(PERMISSION_READY, sync);
    return () => window.removeEventListener(PERMISSION_READY, sync);
  }, []);

  return codes;
}

export function hasPermissionCode(codes: string[], code: string): boolean {
  return codes.includes(code);
}
